import React, { useEffect, useState } from 'react';
import AliceCarousel from 'react-alice-carousel';
import axios from 'axios';
import styles from './Slider_fav.module.css';
import "react-alice-carousel/lib/alice-carousel.css";

const Slider_fav = () => {
  const [movies, setMovies] = useState([]);
  const [loading, setLoading] = useState(true);

  // Функция для загрузки фильмов из OMDb API
  useEffect(() => {
    const fetchMovies = async () => {
      try {
        const response = await axios.get('https://www.omdbapi.com/?apikey=a479eec2&s=popular&type=movie');
        setMovies(response.data.Search || []);
        setLoading(false);
      } catch (error) {
        console.error('Error fetching movies:', error);
        setLoading(false);
      }
    };

    fetchMovies();
  }, []);

  if (loading) return <div>Loading...</div>;

  // Слайдер с фильмами
  const movieItems = movies.map((movie) => (
    <div key={movie.imdbID} className={styles.sliderItem}>
      <img src={movie.Poster} alt={movie.Title} />
      <h4>{movie.Title}</h4>
    </div>
  ));

  return (
    <div className={styles.movieSlider}>
      <AliceCarousel
        mouseTracking
        items={movieItems}
        infinite
        autoPlay
        autoPlayInterval={3000}
        animationDuration={1000}
      />
    </div>
  );
};

export default Slider_fav;
